export const BIDAL_WORD_SET: Set<string> = new Set(BIDAL_WORD_STRING.split(" "));

/** Mirrors the normalization every word in BIDAL_WORD_SET was built
 *  with — see the file header for why this differs slightly from
 *  ihjNormalize (lib/ihj-normalize.ts): بدل's letter bag is more
 *  restrictive than إنسان حيوان جماد's answer validation needs to be. */
export function normalizeBidalWord(input: string): string {
  if (!input) return "";
  let result = input.trim();
  result = result.replace(/[\u064B-\u065F\u0670\u06D6-\u06ED]/g, ""); // diacritics
  result = result.replace(/[أإآٱ]/g, "ا");
  result = result.replace(/ـ/g, ""); // tatweel
  result = result.replace(/ة/g, "ه").replace(/ى/g, "ي").replace(/[ئؤ]/g, "ء");
  return result.trim();
}

/** The actual check attemptMove runs before committing a move — O(1)
 *  Set lookup, no network, no async, safe to call on every keystroke
 *  or drop if ever needed for live feedback, not just on commit. */
export function isValidBidalWord(word: string): boolean {
  return BIDAL_WORD_SET.has(normalizeBidalWord(word));
}
